func init() {
	Catalog = append(Catalog, extCatalog...)
	for i := range Catalog {
		r := &Catalog[i]
		if r.Frameworks == nil {
			if f, ok := frameworksExisting[r.ID]; ok {
				r.Frameworks = f
			}
		}
		if r.DescriptionEN == "" {
			if en, ok := englishExisting[r.ID]; ok {
				r.DescriptionEN, r.RemediationEN = en[0], en[1]
			}
		}
	}
}
